Here's the complete function. It uses only the standard library and follows the 12 rules in order.

```python
import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_TRUTHY = {"y", "yes", "true", "1"}


def _norm_email(raw):
    """Rule 1: normalize an email address."""
    s = raw or ""
    m = re.search(r"<([^<>]*)>", s)          # "Ann Lee <ann@x.org>" -> "ann@x.org"
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            s = local + "@gmail.com"
    return s


def _email_is_valid(e):
    """Rule 2."""
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _norm_phone(raw):
    """Rule 3: return the 10-digit phone if valid, else ""."""
    s = raw or ""
    low = s.lower()
    cuts = [i for i in (low.find("x"), low.find("ext"), low.find("#")) if i != -1]
    if cuts:
        s = s[: min(cuts)]
    digits = "".join(ch for ch in s if ch.isdigit())
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _norm_zip(raw):
    """Rule 4."""
    s = (raw or "").strip()
    m = re.fullmatch(r"(\d{4,5})-\d{4}", s)
    if m:
        s = m.group(1)
    if re.fullmatch(r"\d{4}", s):
        s = "0" + s
    return s if re.fullmatch(r"\d{5}", s) else ""


def _norm_name(raw):
    """Rule 5."""
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        return s.title()
    return s


def _parse_updated(raw, idx):
    """Rule 6."""
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Row {idx}: unrecognized 'updated' value {raw!r}")


def _split_tags(raw):
    """Rule 8 (plus the cleanup from rule 11)."""
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def dedupe_contacts(rows):
    # ---- Normalize every row; drop rows with no valid email or phone (rule 9) ----
    recs = []
    for idx, row in enumerate(rows):
        email = _norm_email(row.get("email"))
        if not _email_is_valid(email):
            email = ""
        phone = _norm_phone(row.get("phone"))
        if not email and not phone:
            continue
        source = (row.get("source") or "").strip().lower()
        recs.append({
            "idx": idx,
            "first_name": _norm_name(row.get("first_name")),
            "last_name": _norm_name(row.get("last_name")),
            "email": email,
            "phone": phone,
            "zip": _norm_zip(row.get("zip")),
            "source": source,
            "manual": source == "manual",
            "dt": _parse_updated(row.get("updated"), idx),
            "tags": _split_tags(row.get("tags")),
            "opted_out": (row.get("opted_out") or "").strip().lower() in _TRUTHY,
        })

    # ---- Union-find for transitive matching (rule 10) ----
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # keep the earlier row as root (not required, just tidy)
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_seen = {}
    for i, r in enumerate(recs):
        keys = []
        if r["email"]:
            keys.append(("email", r["email"]))
        if r["phone"] and r["last_name"]:
            keys.append(("phone", r["phone"], r["last_name"].lower()))
        for k in keys:
            if k in first_seen:
                union(i, first_seen[k])
            else:
                first_seen[k] = i

    groups = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(recs[i])

    # ---- Build one output record per person (rule 11) ----
    def pick(members, field):
        cands = [m for m in members if m[field]]
        if not cands:
            return ""
        best = max(cands, key=lambda m: (m["manual"], m["dt"], -m["idx"]))
        return best[field]

    people = []
    for members in groups.values():
        tags = set()
        for m in members:
            tags |= m["tags"]
        people.append((
            min(m["idx"] for m in members),
            {
                "first_name": pick(members, "first_name"),
                "last_name": pick(members, "last_name"),
                "email": pick(members, "email"),
                "phone": pick(members, "phone"),
                "zip": pick(members, "zip"),
                "tags": ";".join(sorted(tags)),
                "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
                "updated": max(m["dt"] for m in members).strftime("%Y-%m-%d"),
                "source": pick(members, "source"),
            },
        ))

    # ---- Order by earliest input row (rule 12) ----
    people.sort(key=lambda p: p[0])
    return [p[1] for p in people]
```

A few things to check before tomorrow's send:

- **Opted-out people are still in the output.** They're marked `opted_out: "Y"`, which is what the spec asks for. You still need to filter them out when you build the send list, for example with `[p for p in result if p["opted_out"] == "N" and p["email"]]`. That same filter also skips people who have only a phone number.
- **Rows dropped by rule 9 don't count toward opt-outs.** A row with an opt-out flag but no valid email or phone is discarded before matching. It couldn't have been linked to anyone anyway, so this is consistent with the spec. Just be aware it happens.
- **Gmail addresses are output in their normalized form.** For example, `Jane.Doe+news@googlemail.com` becomes `janedoe@gmail.com`. Gmail delivers both forms to the same inbox, so this is fine for sending.
- **Bad dates stop the run.** If an `updated` value doesn't match one of the three formats, the function raises a `ValueError` that names the row. It doesn't guess, because a silently wrong date would change which row's data wins.
- **Ambiguous inputs:** I treated a malformed ZIP+4 whose first part lost its leading zero (`2139-4307`) as ZIP+4, so it becomes `02139`. A phone marker search on "x" also catches "ext", so whichever marker appears first is where the number gets cut.

I'd suggest running it on a sample of the export and comparing row counts before and after, as a quick sanity check. Good luck with the S. 2817 push!
